/**
 * Comprehensive validation metadata providing detailed feedback and improvement
 * guidance
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallValidationMetadata = {
  /** Primary validation result indicating pass or fail status */
  is_valid: boolean;

  /** List of validation issues with detailed field-specific feedback */
  issues?:
    | {
        /** Human-readable issue explanation for user feedback */
        message: string;

        /** Specific field name where validation failed */
        field: string;

        /** Unique validation error code for programmatic handling */
        code: string;
      }[]
    | undefined;

  /** Collection of specific improvement suggestions for user experience */
  suggestions?: string[] | undefined;

  /**
   * Collection of non-critical warnings that don't block validation but
   * inform user
   */
  warnings?: string[] | undefined;
};
